import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over_budget';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Редизайн личного кабинета', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Миграция на новый биллинг', quotaPercent: 88, status: 'active' },
  { id: 'p3', name: 'Мобильное приложение курьера', quotaPercent: 100, status: 'over_budget' },
  { id: 'p4', name: 'Внутренний портал поддержки', quotaPercent: 15, status: 'paused' },
  { id: 'p5', name: 'Аналитика воронки продаж', quotaPercent: 67, status: 'active' },
  { id: 'p6', name: 'Интеграция с CRM партнёра', quotaPercent: 96, status: 'over_budget' },
  { id: 'p7', name: 'Обновление дизайн-системы', quotaPercent: 30, status: 'paused' },
  { id: 'p8', name: 'Модуль отчётов для клиентов', quotaPercent: 54, status: 'active' },
];

const statusFilters: { value: ProjectStatus; label: string }[] = [
  { value: 'active', label: 'В работе' },
  { value: 'paused', label: 'На паузе' },
  { value: 'over_budget', label: 'Превышен бюджет' },
];

const statusMeta: Record<ProjectStatus, { label: string; tone: 'success' | 'default' | 'danger' }> = {
  active: { label: 'В работе', tone: 'success' },
  paused: { label: 'На паузе', tone: 'default' },
  over_budget: { label: 'Превышен бюджет', tone: 'danger' },
};

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeFilters, setActiveFilters] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleFilter = (status: ProjectStatus) => {
    setActiveFilters((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveFilters([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeFilters.length === 0) return projects;
    return projects.filter((project) => activeFilters.includes(project.status));
  }, [activeFilters]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE,
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', maxWidth: '640px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {statusFilters.map((filter) => (
          <JxChip
            key={filter.value}
            active={activeFilters.includes(filter.value)}
            removable={activeFilters.includes(filter.value)}
            onClick={() => toggleFilter(filter.value)}
            onRemove={() => toggleFilter(filter.value)}
          >
            {filter.label}
          </JxChip>
        ))}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные фильтры не попал ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 4px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <JxProgressCircle value={project.quotaPercent} showValue />
                <span style={{ flex: 1, color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}>
                  {project.name}
                </span>
                <JxBadge tone={statusMeta[project.status].tone}>
                  {statusMeta[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

